export const AREA = ['Miami-Dade', 'Broward', 'Palm Beach'].map((n) => ({ '@type': 'AdministrativeArea', name: n + ' County, FL' }));

export const esc = (v) => String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
export const amp = (v) => String(v).replace(/&(?!(?:[a-z]+|#\d+|#x[0-9a-f]+);)/gi, '&amp;');
export const plain = (v) => String(v).replace(/<[^>]+>/g, '').replace(/&amp;/g, '&').replace(/&nbsp;/g, ' ').replace(/&quot;/g, '"').replace(/&#x27;/g, "'");

