const read = (rel) => fs.readFileSync(path.join(process.cwd(), rel), 'utf8');

// Analytics snippets: copied from /work/ so every page loads the same tags.
export function trackingHead() {
  const w = read('work/index.html').split('\n');
  return w.filter((l) => l.startsWith('<script async src="https://www.googletagmanager.com') || l.startsWith("<script>window.dataLayer") || l.startsWith('<script type="text/javascript">window.addEventListener(\'load\'')).join('\n');
}

// Cards from /work/ (image, alt, title, facts), so alt texts and sizes stay identical to the source page.
export function workCards() {
  const html = read('work/index.html');
  const out = {};
  const re = /<a class="card[^"]*" href="(\/projects\/[^"]+)"><img src="([^"]+)" srcset="([^"]+)" sizes="[^"]*" width="(\d+)" height="(\d+)" alt="([^"]*)"[^>]*><span class="tag">([^<]+)<\/span><div class="cap"><h3>([^<]+)<\/h3><div class="m">((?:<span>[^<]*<\/span>)+)<\/div>/g;
  let m;
  while ((m = re.exec(html))) {
    const small = m[3].split(',').map((s) => s.trim().split(' ')[0]).find((u) => /-t\.jpg$/.test(u)) || m[2];
    out[m[1]] = { href: m[1], src: small, w: +m[4], h: +m[5], alt: m[6], tag: m[7], title: m[8], meta: [...m[9].matchAll(/<span>([^<]*)<\/span>/g)].map((x) => x[1]) };
  }
  return out;
}

const CARD_ES = {
  '/projects/villa-white-courtyard-spiral-stair.html': ['Villa blanca con patio', 'Sala de doble altura con una escalera de caracol blanca esculpida'],
  '/projects/villa-grey-marble-walnut.html': ['Villa de mármol gris y nogal', 'Sala de doble altura con un sofá seccional blanco y una escalera de mármol gris'],
  '/projects/villa-double-height-rooftop-pool.html': ['Villa de doble altura con azotea', 'Sala de doble altura con una escultura de luz LED suspendida y una escalera de mármol'],
  '/projects/penthouse-raised-ceilings-renovation.html': ['Penthouse con techos elevados', 'Sala de un penthouse con mesas de centro de piedra escultóricas y carpintería de roble'],
  '/projects/apartment-oak-stone-open-plan.html': ['Apartamento de roble y piedra', 'Sala de planta abierta con una isla de cocina de piedra'],
  '/projects/apartment-one-bedroom-black-stone.html': ['Apartamento de un dormitorio en piedra negra', 'Cocina con una isla de piedra negra y piso de madera'],
  '/projects/apartment-light-oak-three-bedroom.html': ['Apartamento de tres dormitorios en roble claro', 'Cocina de roble claro con piso en espiga y una mesa de comedor redonda'],
  '/projects/apartment-classic-moulding-two-bedroom.html': ['Apartamento clásico de dos dormitorios con molduras', 'Dormitorio con una obra de arte de grullas y cortinas translúcidas'],
};
const TAG_ES = { VILLA: 'VILLA', APARTMENT: 'APARTAMENTO', PENTHOUSE: 'PENTHOUSE' };
const metaEs = (m) => m.replace('COURTYARD POOL', 'PISCINA EN PATIO').replace('SQ FT', 'PIES²').replace('36 FT CEILINGS', 'TECHOS DE 36 PIES').replace('BEDROOMS', 'DORMITORIOS').replace('MONTHS', 'MESES');

export function cardsHtml(cards, lang, withMeta = true) {
  return '<div class="grid">' + cards.map((c0) => {
    let c = c0;
    if (lang === 'es' && CARD_ES[c0.href]) c = { ...c0, title: CARD_ES[c0.href][0], alt: CARD_ES[c0.href][1], tag: TAG_ES[c0.tag] || c0.tag, meta: c0.meta.map(metaEs) };
    const dim = c.dim || [c.w, c.h];
    return `<a class="card" href="${c.href}"><img src="${c.src}" width="${dim[0]}" height="${dim[1]}" alt="${c.alt}" loading="lazy" decoding="async"><span class="tag">${c.tag}</span><div class="cap"><h3>${c.title}</h3>${withMeta && c.meta && c.meta.length ? '<div class="m">' + c.meta.map((x) => `<span>${x}</span>`).join('') + '</div>' : ''}<span class="go">${lang === 'es' ? 'Ver proyecto' : lang === 'ru' ? 'Смотреть проект' : 'View project'} &#8594;</span></div></a>`;
  }).join('') + '</div>';
}

