const MENU_JS = `(function(){var btn=document.querySelector('.menu-btn'),nav=document.getElementById('mnav');if(!btn||!nav)return;function set(open){btn.setAttribute('aria-expanded',open?'true':'false');nav.hidden=!open;document.body.classList.toggle('menu-open',open);document.body.style.overflow=open?'hidden':''}btn.addEventListener('click',function(){set(nav.hidden)});nav.addEventListener('click',function(e){if(e.target.closest('a'))set(false)});document.addEventListener('keydown',function(e){if(e.key==='Escape'&&!nav.hidden)set(false)});matchMedia('(min-width:901px)').addEventListener('change',function(m){if(m.matches&&!nav.hidden)set(false)})})();`;

// page: { lang, slug, title, desc, h1, label, lede, crumbs:[[name,url]], meta, ctas:[[label,href,cls]], sections:[{id,h2,label,html,alt}],
//         faq:[{q,a}], ctaH, ld:[extra @graph nodes], ogImage, ogAlt, noindex, langs:['en','es'], type:'Service'|'Article'|'WebPage', ldService }
export function render(page) {
  const lang = page.lang;
  const t = UI[lang];
  const url = ORIGIN + (lang === 'en' ? '' : '/' + lang) + page.slug;
  const title = page.title;
  const ogImage = page.ogImage || ORIGIN + '/media/lp/og.jpg';
  const graph = [];
  const crumbs = [[t.home, ORIGIN + t.homeHref], ...page.crumbs.map(([n, u]) => [n, u ? ORIGIN + u : url])];
  graph.push({ '@type': 'BreadcrumbList', itemListElement: crumbs.map(([n, u], i) => ({ '@type': 'ListItem', position: i + 1, name: plain(n), item: u })) });
  const webpage = { '@type': 'WebPage', '@id': url + '#webpage', name: plain(title), url, description: plain(page.desc), inLanguage: lang, isPartOf: { '@id': ORIGIN + '/#website' } };
  if (page.service) {
    const svc = { '@type': 'Service', '@id': url + '#service', provider: BIZ, areaServed: AREA, url, ...page.service };
    graph.push(svc);
    webpage.about = { '@id': url + '#service' };
  }
  if (page.article) {
    graph.push({ '@type': 'Article', '@id': url + '#article', headline: plain(page.h1), description: plain(page.desc), inLanguage: lang, url, mainEntityOfPage: { '@id': url + '#webpage' }, author: BIZ, publisher: BIZ, datePublished: page.article.date, dateModified: page.article.date, image: ogImage });
  }
  if (page.about) webpage.about = page.about;
  graph.unshift(webpage);
  for (const n of page.ld || []) graph.push(n);
  if (page.faq && page.faq.length) {
    graph.push({ '@type': 'FAQPage', mainEntity: page.faq.map((f) => ({ '@type': 'Question', name: plain(f.q), acceptedAnswer: { '@type': 'Answer', text: plain(f.a) } })) });
  }
  const ld = JSON.stringify({ '@context': 'https://schema.org', '@graph': graph });

  const alt = (page.langs || [lang]).length > 1
    ? page.langs.map((l) => `<link rel="alternate" hreflang="${l}" href="${ORIGIN}${l === 'en' ? '' : '/' + l}${page.slug}">`).join('\n') + `\n<link rel="alternate" hreflang="x-default" href="${ORIGIN}${page.slug}">\n`
    : '';
  const cyr = lang === 'ru';
  const nav = t.nav.map(([n, h]) => `<a href="${h}">${n}</a>`).join('');
  const crumbHtml = `<a href="${t.homeHref}">${t.home}</a>` + page.crumbs.map(([n, u]) => ' / ' + (u ? `<a href="${u}">${n}</a>` : n)).join('');
  const sections = page.sections.map((s, i) => `<section class="sec${s.alt ? ' alt' : ''}"${s.id ? ` id="${s.id}"` : ''}><div class="wrap">${s.label ? `<div class="label">${s.label}</div>` : ''}<h2>${s.h2}</h2><div class="prose">${s.html}</div></div></section>`).join('\n');
  const faq = page.faq && page.faq.length
    ? `<section class="sec${page.faqAlt === false ? '' : ' alt'}" id="faq"><div class="wrap"><div class="label">FAQ</div><h2>${t.faq}</h2><div class="faq">${page.faq.map((f) => `<details><summary>${amp(f.q)}</summary><p>${amp(f.a)}</p></details>`).join('')}</div></div></section>`
    : '';
  const ctas = (page.ctas || [[t.btnBook, t.bookHref, 'btn-ink']]).map(([l, h, c]) => `<a class="btn ${c}" href="${h}">${l}</a>`).join('');
  const footLinks = t.links.map(([n, h, l]) => `<a href="${h}"${l ? ` hreflang="${l}" lang="${l}"` : ''}>${n}</a>`).join('');
  const robots = page.noindex ? '<meta name="robots" content="noindex, nofollow">\n' : '';
  return `<!DOCTYPE html>
<html lang="${lang}">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<meta name="theme-color" content="#FAF6EE">
<title>${esc(title)}</title>
${robots}<meta name="description" content="${esc(page.desc)}">
<link rel="canonical" href="${url}">
${alt}<meta property="og:type" content="${page.article ? 'article' : 'website'}">
<meta property="og:site_name" content="M5 Studio Miami">
<meta property="og:locale" content="${LOCALE[lang]}">
<meta property="og:title" content="${esc(title)}">
<meta property="og:description" content="${esc(page.desc)}">
<meta property="og:image" content="${ogImage}">
<meta property="og:image:width" content="1200"><meta property="og:image:height" content="630">
<meta property="og:url" content="${url}">
<meta name="twitter:card" content="summary_large_image">
<link rel="icon" type="image/svg+xml" href="/favicon.svg">
<link rel="preload" as="font" type="font/woff2" href="/fonts/cormorant-garamond-${cyr ? 'cyrillic' : 'latin'}.woff2" crossorigin>
<link rel="stylesheet" href="/tokens.css">
${trackingHead()}
<script type="application/ld+json">${ld}</script>
<style>${CSS}</style>
<script defer src="/analytics.js"></script>
</head>
<body>
<header>
  <a class="logo" href="${t.homeHref}" aria-label="M5">${LOGO}</a>
  <nav class="h-nav" aria-label="Main">${nav}</nav>
  <div class="h-right"><a class="h-cta" href="${t.bookHref}">${t.book}</a></div>
  <button class="menu-btn" type="button" aria-expanded="false" aria-controls="mnav" aria-label="${t.menu}"><span></span><span></span></button>
</header>
<div class="mnav" id="mnav" hidden>
  <nav class="mnav-links" aria-label="Main">${nav}</nav>
  <a class="btn btn-bone mnav-cta" href="${t.bookHref}">${t.book}</a>
  <a class="mnav-wa" href="https://wa.me/17864074441" target="_blank" rel="noopener">WhatsApp</a>
</div>

<main>
<section class="top">
  <div class="wrap">
    <div class="crumb">${crumbHtml}</div>
    <div class="label">${page.label}</div>
    <h1>${page.h1}</h1>
    <p class="lede">${page.lede}</p>
    <div class="ctas">${ctas}</div>
    ${page.meta ? `<div class="meta">${page.meta}</div>` : ''}
  </div>
</section>

${sections}
${faq}
</main>

<section class="cta">
  <div class="wrap">
    <div class="label" style="color:#D9B87C">${t.ctaLabel}</div>
    <h2>${page.ctaH}</h2>
    <div class="sub">${t.ctaSub}</div>
    <div class="btns">
      <a class="btn btn-bone" href="${t.bookHref}">${t.btnBook}</a>
      <a class="btn btn-line" style="border-color:rgba(244,238,228,.55);color:var(--bone)" target="_blank" rel="noopener" href="${CAL}" onclick="if(window.m5track)m5track('booking_click',{source:'${page.track || 'page'}'})">${t.btnCal}</a>
      <a class="btn btn-wa" target="_blank" rel="noopener" href="https://wa.me/17864074441" onclick="if(window.m5track)m5track('whatsapp_click')">${t.btnWa}</a>
    </div>
  </div>
</section>

<footer>
  <div class="wrap">
    <nav class="f-nav" aria-label="${t.footNav}">${footLinks}</nav>
    <div class="f-bot"><span>${t.foot}<a href="${t.privacyHref}" style="color:inherit">${t.privacy}</a></span><span><a href="mailto:hello@m5miami.com">hello@m5miami.com</a> · <a href="https://instagram.com/m5miami" target="_blank" rel="noopener">Instagram</a> · Miami-Dade · Broward · Palm Beach</span></div>
  </div>
</footer>
<a class="wa" href="https://wa.me/17864074441" aria-label="${t.waAria}" onclick="if(window.m5track)m5track('whatsapp_click')">${WA_ICON}</a>
<script>
${MENU_JS}
</script>
</body>
</html>
`;
}
